//! Cargo-driven `avifil32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "___ImageBase", Some(0x77160000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "__ImageBase", Some(0x7ff67000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "__ImageBase", Some(0x7ff67000000u64)),
        o => panic!("avifil32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/avifil32/avifil32_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:pseh", "import:msacm32", "import:msvfw32", "import:winmm", "import:ole32", "import:user32", "import:advapi32", "import:rpcrt4", "import:ucrtbase", "import:kernel32", "import:ntdll", "engine:c:vcstartup", "engine:chkstk"],
        "x86_64" => &["dll/win32/avifil32/avifil32_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:pseh", "import:msacm32", "import:msvfw32", "import:winmm", "import:ole32", "import:user32", "import:advapi32", "import:rpcrt4", "import:ucrtbase", "import:kernel32", "import:ntdll", "engine:c:vcstartup"],
        "aarch64" => &["dll/win32/avifil32/avifil32_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:pseh", "import:msacm32", "import:msvfw32", "import:winmm", "import:ole32", "import:user32", "import:advapi32", "import:rpcrt4", "import:ucrtbase", "import:kernel32", "import:ntdll", "engine:c:vcstartup", "engine:chkstk"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/avifil32",
        "dll/win32/avifil32",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["ENTRY_PREFIX=avifil32_", "WINVER=0x502", "_WIN32_WINNT=0x600", "__WINESRC__"];

    Linker::new(target_json)
        .c_from_compile_db("avifil32_shims", &["dll/win32/avifil32/acmstream.c", "dll/win32/avifil32/api.c", "dll/win32/avifil32/avifile.c", "dll/win32/avifil32/editstream.c", "dll/win32/avifil32/extrachunk.c", "dll/win32/avifil32/factory.c", "dll/win32/avifil32/getframe.c", "dll/win32/avifil32/icmstream.c", "dll/win32/avifil32/tmpfile.c", "dll/win32/avifil32/wavfile.c", "dll/win32/avifil32/guid.c", "dll/win32/avifil32/avifil32_p.c", "dll/win32/avifil32/proxy.dlldata.c"])
        .rc("dll/win32/avifil32/avifil32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/avifil32/avifil32.spec", "avifil32.dll")
        .import_lib("dll/win32/msacm32/msacm32.spec", "msacm32.dll", "msacm32")
        .import_lib("dll/win32/msvfw32/msvfw32.spec", "msvfw32.dll", "msvfw32")
        .import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/ucrtbase/ucrtbase.spec", "ucrtbase.dll", "ucrtbase")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
